import java.util.*;

class Solution {
    public void nextArrangement(int[] nums) {
        int n = nums.length;
        int i = n - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) i--;    // find the pivot
        if (i >= 0) {
            int j = n - 1;
            while (nums[j] <= nums[i]) j--;                // smallest bigger value on the right
            swap(nums, i, j);
        }
        // tail is descending: reverse to make it the smallest
        for (int l = i + 1, r = n - 1; l < r; l++, r--) swap(nums, l, r);
    }

    private void swap(int[] a, int x, int y) {
        int t = a[x]; a[x] = a[y]; a[y] = t;
    }
}

